enum AuthProvider { Lti = 1, Oidc = 2 }

sealed class HeaderMap
{
    private readonly Dictionary<string, string> _headers = new(StringComparer.OrdinalIgnoreCase);
    public string this[string name]
    {
        get => _headers[name];
        set => _headers[name] = value;
    }
}

static (AuthProvider provider, string issuer) Parse(string raw)
{
    return raw.StartsWith("lti:", StringComparison.Ordinal)
        ? (AuthProvider.Lti, raw[4..])
        : (AuthProvider.Oidc, raw);
}
